<template><EnterpriseAuthShell><div class="auth-panel"><h2>找回密码</h2><p class="subtitle">重置链接将在一小时内有效</p><el-result v-if="sent" icon="success" title="请求已提交" sub-title="如果账号存在，重置邮件会发送到该邮箱"><template #extra><el-button @click="router.push('/enterprise/login')">返回登录</el-button></template></el-result><el-form v-else ref="formRef" :model="form" :rules="rules" label-position="top"><el-form-item label="企业邮箱" prop="email"><el-input v-model="form.email" type="email" size="large" :prefix-icon="Message" /></el-form-item><el-button type="primary" size="large" :loading="loading" @click="submit">发送重置邮件</el-button><div class="auth-links"><RouterLink to="/enterprise/login">返回登录</RouterLink></div></el-form></div></EnterpriseAuthShell></template>
<script setup lang="ts">import { reactive, ref } from 'vue'; import { RouterLink, useRouter } from 'vue-router'; import type { FormInstance, FormRules } from 'element-plus'; import { Message } from '@element-plus/icons-vue'; import EnterpriseAuthShell from '@/components/enterprise/EnterpriseAuthShell.vue'; import { enterpriseAPI } from '@/api/enterprise'; const router=useRouter(), formRef=ref<FormInstance>(), loading=ref(false), sent=ref(false), form=reactive({email:''}); const rules:FormRules={email:[{required:true,type:'email',message:'请输入有效邮箱',trigger:'blur'}]}; async function submit(){if(!await formRef.value?.validate().catch(()=>false))return;loading.value=true;try{await enterpriseAPI.forgotPassword(form.email);sent.value=true}finally{loading.value=false}}</script>
